(function () {
'use strict';
var wrap = document.querySelector('.l2d-wrap');
if (!wrap) return;
var csrfEl = document.querySelector('input[name="csrfmiddlewaretoken"]');
var csrf = csrfEl ? csrfEl.value : '';
var statsEl = document.getElementById('l2d-stats');
var toastEl = null;
var toastTimer = null;
function toast(text, isErr) {
if (!toastEl) {
toastEl = document.createElement('div');
toastEl.className = 'l2d-toast';
document.body.appendChild(toastEl);
}
toastEl.textContent = text;
toastEl.className = 'l2d-toast show' + (isErr ? ' err' : '');
clearTimeout(toastTimer);
toastTimer = setTimeout(function () { toastEl.className = 'l2d-toast'; }, 2200);
}
function renderStats(s) {
if (!statsEl || !s) return;
document.getElementById('l2d-on').textContent = s.enabled;
document.getElementById('l2d-off').textContent = s.disabled;
}
function post(params) {
var body = new URLSearchParams();
body.append('csrfmiddlewaretoken', csrf);
Object.keys(params).forEach(function (k) { body.append(k, params[k]); });
return fetch(window.location.pathname, {
method: 'POST',
credentials: 'same-origin',
headers: {
'X-Requested-With': 'XMLHttpRequest',
'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8'
},
body: body.toString()
}).then(function (r) {
if (!r.ok) throw new Error('HTTP ' + r.status);
return r.json();
});
}
function repaint(enabledMap) {
var cards = wrap.querySelectorAll('.l2d-card');
var on = 0;
Array.prototype.forEach.call(cards, function (card) {
var id = card.getAttribute('data-id');
var want = enabledMap ? enabledMap[id] : null;
var input = card.querySelector('input[data-model-id]');
if (want !== null && want !== undefined) input.checked = want;
var isOn = input.checked;
card.classList.toggle('is-on', isOn);
card.classList.toggle('is-off', !isOn);
card.querySelector('.l2d-state').textContent = isOn ? '已启用' : '已关闭';
if (isOn) on++;
});
renderStats({ enabled: on, disabled: cards.length - on });
}
wrap.addEventListener('change', function (e) {
var input = e.target;
if (!input || input.type !== 'checkbox' || !input.hasAttribute('data-model-id')) return;
var card = input.closest('.l2d-card');
var id = input.getAttribute('data-model-id');
var want = input.checked;
card.classList.add('saving');
post({ action: 'toggle', model_id: id, enabled: want ? 1 : 0 }).then(function (res) {
card.classList.remove('saving');
if (!res.ok) {
input.checked = !want;
toast(res.note || '操作失败', true);
return;
}
card.classList.toggle('is-on', want);
card.classList.toggle('is-off', !want);
card.querySelector('.l2d-state').textContent = want ? '已启用' : '已关闭';
renderStats(res.stats);
toast(res.note);
}).catch(function (err) {
card.classList.remove('saving');
input.checked = !want;
toast('保存失败：' + err.message, true);
});
});
wrap.addEventListener('click', function (e) {
var btn = e.target.closest('[data-bulk]');
if (!btn) return;
var want = btn.getAttribute('data-bulk') === '1';
var group = btn.getAttribute('data-group') || '';
btn.disabled = true;
post({ action: 'bulk', enabled: want ? 1 : 0, group: group }).then(function (res) {
btn.disabled = false;
if (!res.ok) { toast(res.note || '操作失败', true); return; }
if (group) {
var section = wrap.querySelector('.l2d-group[data-group="' + group + '"]');
var map = {};
if (section) {
Array.prototype.forEach.call(section.querySelectorAll('.l2d-card'), function (c) {
map[c.getAttribute('data-id')] = want;
});
}
repaint(map);
renderStats(res.stats);
} else {
repaint(null);
renderStats(res.stats);
}
toast(res.note);
}).catch(function (err) {
btn.disabled = false;
toast('保存失败：' + err.message, true);
});
});
})();